'use strict';
function canHitTutorialMonster(source){return player.tutorialProgress==='useActive'&&source?.origin==='manual'&&source.direct&&!source.proc}
function monsterSurfaceRoute(index){const first=platforms[index];if(!first)return [];const route=[index];let changed=true;while(changed){changed=false;for(let i=0;i<platforms.length;i++){const p=platforms[i];if(route.includes(i)||p.layer!==first.layer)continue;if(route.some(j=>{const q=platforms[j];return Math.abs(p.x-(q.x+q.w))<.5&&Math.abs(p.y-platformSurface(q,q.x+q.w))<.5||Math.abs(q.x-(p.x+p.w))<.5&&Math.abs(q.y-platformSurface(p,p.x+p.w))<.5})){route.push(i);changed=true}}}return route.sort((a,b)=>platforms[a].x-platforms[b].x)}
function updateMonsterSurface(m){const route=m.patrolPlatforms||monsterSurfaceRoute(m.p);if(!route.length)return;const next=route.find(i=>m.x>=platforms[i].x-.01&&m.x<=platforms[i].x+platforms[i].w+.01);if(next!==undefined)m.p=next;if(platforms[m.p])m.y=platformSurface(platforms[m.p],m.x)}
function renderCharacterStatTabs(){const nav=$('characterStatTabs');nav.replaceChildren();for(const [key,title]of [['status','1 · Status'],['bonus','2 · Bonus Stat']]){const button=document.createElement('button');button.type='button';button.textContent=title;button.setAttribute('aria-pressed',String(characterStatPage===key));button.onclick=()=>{hideUpgradeTooltip();characterStatPage=key;renderCharacterStatTabs()};nav.append(button)}$('statusValues').hidden=characterStatPage!=='status';$('specialValues').hidden=characterStatPage!=='bonus'}
function renderSkillSources(body){body.querySelector('.skill-sources')?.remove();const bar=document.createElement('div');bar.className='skill-sources';bar.setAttribute('aria-label','อาวุธและ Emblem ที่สวม');for(const [type,weapon,label]of [['main',weaponInHand('main'),'อาวุธหลัก'],['emblem',equippedEmblemType(),'Emblem']]){const chip=document.createElement('div');chip.className='skill-source '+type;const icon=document.createElement('span');icon.innerHTML=weapon?(type==='emblem'?emblemIcon(weapon):weaponIcon(weapon)):'';const text=document.createElement('span');text.textContent=label+': '+(weapon?WEAPON_NAMES[weapon]:'ไม่ได้สวม');chip.append(icon,text);bar.append(chip)}const tabs=body.querySelector('.support-tabs');if(tabs)tabs.after(bar);else body.prepend(bar)}
function markSkillSourceTabs(tabs){for(const tab of tabs.children){const main=tab.dataset.weapon===weaponInHand('main'),emblem=tab.dataset.weapon===equippedEmblemType();tab.classList.toggle('source-main',main);tab.classList.toggle('source-emblem',emblem);if(main||emblem){const badge=document.createElement('small');badge.className='source-type-badge';badge.textContent=main&&emblem?'หลัก + E':emblem?'Emblem':'หลัก';tab.append(badge)}if(emblem)tab.title=WEAPON_NAMES[tab.dataset.weapon]+' · Emblem ที่สวม'}}
